declare(strict_types=1);requireRole('subject-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='vision-camp';$db=database();$user=(int)$_SESSION['user_id'];$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);
function campRedirect(string $message):never{$_SESSION['flash_success']=$message;unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=vision-camp');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';$action=(string)($_POST['action']??'');
 if(!$errors)try{
  if($action==='create'){$ds=filter_input(INPUT_POST,'ds_division_id',FILTER_VALIDATE_INT);$supplier=filter_input(INPUT_POST,'supplier_id',FILTER_VALIDATE_INT);$reason=trim((string)($_POST['justification']??''));if(!$ds||!$supplier||mb_strlen($reason)<10)throw new RuntimeException('Select a division and vendor and provide a justification.');$db->prepare('INSERT INTO vision_camps(ds_division_id,supplier_id,justification,requested_by) VALUES(:ds,:supplier,:reason,:user)')->execute(['ds'=>$ds,'supplier'=>$supplier,'reason'=>$reason,'user'=>$user]);campRedirect('Vendor contact request submitted to Admin.');}
  if($action==='register'){$camp=filter_input(INPUT_POST,'camp_id',FILTER_VALIDATE_INT);$name=trim((string)($_POST['full_name']??''));$nic=strtoupper(trim((string)($_POST['nic']??'')));$address=trim((string)($_POST['address']??''));if(!$camp||mb_strlen($name)<2||!preg_match('/^(?:[0-9]{9}[VX]|[0-9]{12})$/',$nic)||mb_strlen($address)<5)throw new RuntimeException('Enter attendee full name, valid NIC, and home address.');$q=$db->prepare("SELECT id FROM vision_camps WHERE id=:id AND requested_by=:user AND stage='vendor-approved'");$q->execute(['id'=>$camp,'user'=>$user]);if(!$q->fetchColumn())throw new RuntimeException('Attendees can only be registered after vendor approval.');$db->prepare('INSERT INTO vision_camp_beneficiaries(camp_id,full_name,nic,address) VALUES(:camp,:name,:nic,:address)')->execute(['camp'=>$camp,'name'=>$name,'nic'=>$nic,'address'=>$address]);campRedirect('Camp attendee registered.');}
  if($action==='request-release'){$camp=filter_input(INPUT_POST,'camp_id',FILTER_VALIDATE_INT);$date=(string)($_POST['camp_date']??'');if(!$camp||!DateTimeImmutable::createFromFormat('Y-m-d',$date))throw new RuntimeException('Select a valid camp date.');$db->beginTransaction();$q=$db->prepare("SELECT id FROM vision_camps WHERE id=:id AND requested_by=:user AND stage='vendor-approved' FOR UPDATE");$q->execute(['id'=>$camp,'user'=>$user]);if(!$q->fetchColumn())throw new RuntimeException('Camp is not ready for a goods release request.');$q=$db->prepare('SELECT COUNT(*) FROM vision_camp_beneficiaries WHERE camp_id=:camp');$q->execute(['camp'=>$camp]);$count=(int)$q->fetchColumn();if($count<1)throw new RuntimeException('Register at least one beneficiary before requesting goods release.');$db->prepare("UPDATE vision_camps SET proposed_date=:date,people_identified=:count,attended_count=:count,stage='awaiting-goods-release' WHERE id=:id")->execute(['date'=>$date,'count'=>$count,'id'=>$camp]);$db->commit();campRedirect("Goods release requested for $count registered beneficiary(s).");}
  if($action==='outcome'){$attendee=filter_input(INPUT_POST,'attendee_id',FILTER_VALIDATE_INT);$outcome=(string)($_POST['outcome']??'');$reason=trim((string)($_POST['reason']??''));if(!$attendee||!in_array($outcome,['distributed','handed-over','rejected'],true))throw new RuntimeException('Select a valid outcome.');if($outcome==='rejected'&&$reason==='')throw new RuntimeException('A rejection reason is mandatory.');$db->beginTransaction();$q=$db->prepare("SELECT cb.*,vc.ds_division_id,vc.id camp_id FROM vision_camp_beneficiaries cb JOIN vision_camps vc ON vc.id=cb.camp_id WHERE cb.id=:id AND vc.requested_by=:user AND vc.stage='distribution-in-progress' AND cb.outcome='pending' FOR UPDATE");$q->execute(['id'=>$attendee,'user'=>$user]);$a=$q->fetch();if(!$a)throw new RuntimeException('Attendee is no longer awaiting an outcome.');if($outcome==='handed-over'){$q=$db->prepare("SELECT id FROM users WHERE role='social-service-officer' AND status='active' AND ds_division_id=:ds ORDER BY id LIMIT 1");$q->execute(['ds'=>$a['ds_division_id']]);$sso=(int)$q->fetchColumn();if(!$sso)throw new RuntimeException('No active SSO is assigned to this DS Division.');$q=$db->prepare("SELECT id FROM inventory_items WHERE item_name IN ('Spectacles','Glasses') ORDER BY FIELD(item_name,'Spectacles','Glasses') LIMIT 1");$q->execute();$item=$q->fetchColumn()?:null;$db->prepare("INSERT INTO vision_camp_handovers(camp_id,camp_beneficiary_id,beneficiary_id,item_id,quantity,officer_id,status,handed_by) VALUES(:camp,:attendee,NULL,:item,1,:sso,'pending',:user)")->execute(['camp'=>$a['camp_id'],'attendee'=>$attendee,'item'=>$item,'sso'=>$sso,'user'=>$user]);}$db->prepare('UPDATE vision_camp_beneficiaries SET outcome=:outcome,rejection_reason=:reason,processed_by=:user,processed_at=NOW() WHERE id=:id')->execute(['outcome'=>$outcome,'reason'=>$outcome==='rejected'?$reason:null,'user'=>$user,'id'=>$attendee]);$q=$db->prepare("SELECT COUNT(*) total,SUM(outcome='distributed') distributed,SUM(outcome='handed-over') handed,SUM(outcome='pending') pending FROM vision_camp_beneficiaries WHERE camp_id=:camp");$q->execute(['camp'=>$a['camp_id']]);$totals=$q->fetch();$stage=(int)$totals['pending']===0?'completed':'distribution-in-progress';$db->prepare('UPDATE vision_camps SET distributed_count=:distributed,handed_over_count=:handed,attended_count=:total,stage=:stage WHERE id=:id')->execute(['distributed'=>$totals['distributed'],'handed'=>$totals['handed'],'total'=>$totals['total'],'stage'=>$stage,'id'=>$a['camp_id']]);$db->commit();campRedirect('Beneficiary outcome recorded.');}
  throw new RuntimeException('Invalid camp action.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to update Vision Camp.';}
}
try{$divisions=$db->query("SELECT ds.id,ds.name ds_name,d.name district_name FROM ds_divisions ds JOIN districts d ON d.id=ds.district_id WHERE ds.status='active' ORDER BY d.name,ds.name")->fetchAll();$suppliers=$db->query("SELECT id,company_name FROM suppliers WHERE status='active' ORDER BY company_name")->fetchAll();$q=$db->prepare("SELECT vc.*,ds.name ds_name,d.name district_name,s.company_name,u.full_name requester_name,(SELECT COUNT(*) FROM vision_camp_beneficiaries cb WHERE cb.camp_id=vc.id) registered FROM vision_camps vc JOIN ds_divisions ds ON ds.id=vc.ds_division_id JOIN districts d ON d.id=ds.district_id JOIN suppliers s ON s.id=vc.supplier_id JOIN users u ON u.id=vc.requested_by WHERE vc.requested_by=:user ORDER BY vc.id DESC");$q->execute(['user'=>$user]);$camps=$q->fetchAll();$q=$db->prepare("SELECT cb.*,vc.stage FROM vision_camp_beneficiaries cb JOIN vision_camps vc ON vc.id=cb.camp_id WHERE vc.requested_by=:user ORDER BY cb.id");$q->execute(['user'=>$user]);$attendees=$q->fetchAll();$counts=[];foreach($camps as $camp)$counts[$camp['stage']]=($counts[$camp['stage']]??0)+1;}catch(PDOException $e){error_log($e->getMessage());$divisions=$suppliers=$camps=$attendees=[];$counts=[];$errors[]='Vision Camp workflow is unavailable.';}
?>
