?=(int)$camp['id']?>"><input name="full_name" placeholder="Full name" required><input name="nic" placeholder="NIC number" required><input name="address" placeholder="Home address" required><button class="admin-primary-action">Add Attendee</button></form><form method="post" class="vision-release-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="request-release"><input type="hidden" name="camp_id" value="<?=(int)$camp['id']?>"><input type="date" name="camp_date" required><button class="approve-button" <?=!(int)$camp['registered']?'disabled':''?>>Request <?=(int)$camp['registered']?> Spectacles</button></form><?php endif;?><?php if($campPeople):?><table class="vision-attendee-table"><thead><tr><th>Name</th><th>NIC</th><th>Outcome / Action</th></tr></thead><tbody><?php foreach($campPeople as $person):?><tr><td><?=htmlspecialchars($person['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($person['nic'],ENT_QUOTES,'UTF-8')?></td><td><?php if($camp['stage']==='distribution-in-progress'&&$person['outcome']==='pending'):?><form method="post" class="vision-outcome-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="outcome"><input type="hidden" name="attendee_id" value="<?=(int)$person['id']?>"><input name="reason" placeholder="Reason if rejected"><button name="outcome" value="distributed" class="approve-button">Distributed</button><button name="outcome" value="handed-over">Hand Over</button><button name="outcome" value="rejected" class="reject-button">Reject</button></form><?php else:?><?=ucwords(str_replace('-',' ',$person['outcome']))?><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></details></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
